import{_ as o,o as r,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Delivering Enterprise-Grade Object Storage- Bloomberg’s IAM Journey in a Multi-Tenant Arch... S. Gao","description":"","frontmatter":{"title":"Delivering Enterprise-Grade Object Storage- Bloomberg’s IAM Journey in a Multi-Tenant Arch... S. Gao","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Object Storage","Multi-Tenancy","IAM","Bloomberg"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Delivering_Enterprise-Grade_Object_Storage_-_Bloomberg_s_IAM_Journey_in_a_Multi-Tenant_Arch..._S._Gao.md","filePath":"posts/2025/Delivering_Enterprise-Grade_Object_Storage_-_Bloomberg_s_IAM_Journey_in_a_Multi-Tenant_Arch..._S._Gao.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Delivering_Enterprise-Grade_Object_Storage_-_Bloomberg_s_IAM_Journey_in_a_Multi-Tenant_Arch..._S._Gao.md"};function l(i,e,s,g,_,h){return r(),t("div",null,[...e[0]||(e[0]=[a('<h3 id="ceph-会议纪要-bloomberg-企业级对象存储实践" tabindex="-1"><strong>Ceph 会议纪要 - Bloomberg 企业级对象存储实践</strong> <a class="header-anchor" href="#ceph-会议纪要-bloomberg-企业级对象存储实践" aria-label="Permalink to &quot;**Ceph 会议纪要 - Bloomberg 企业级对象存储实践**&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1"><strong>会议基本信息</strong> <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;**会议基本信息**&quot;">​</a></h4><ul><li><strong>演讲人</strong>：Asan（Bloomberg）</li><li><strong>主题</strong>：Bloomberg 基于 Ceph 构建的企业级多租户对象存储实践</li><li><strong>关键词</strong>：Ceph, RGW, multi-tenancy, IAM, Squid, QoS, S3 compatibility</li></ul><h4 id="bloomberg-背景与-ceph-规模" tabindex="-1"><strong>Bloomberg 背景与 Ceph 规模</strong> <a class="header-anchor" href="#bloomberg-背景与-ceph-规模" aria-label="Permalink to &quot;**Bloomberg 背景与 Ceph 规模**&quot;">​</a></h4><ul><li>Bloomberg 作为全球金融科技公司，每日处理海量金融数据。</li><li>使用 Ceph 构建 10 个集群，覆盖多个数据中心，最大单集群拥有 4500 个 OSDs，存储容量达 77PB。</li><li>提供统一 S3 兼容对象存储（RGW）和块存储（RBD）服务。</li></ul><h4 id="多租户模型设计与挑战" tabindex="-1"><strong>多租户模型设计与挑战</strong> <a class="header-anchor" href="#多租户模型设计与挑战" aria-label="Permalink to &quot;**多租户模型设计与挑战**&quot;">​</a></h4><ul><li><strong>核心需求</strong>：资源隔离、策略管控、透明性、权限管理。</li><li><strong>实现方案</strong>：租户映射、自研 UI 管理系统、预定义角色。</li><li><strong>IAM 集成</strong>：过渡到 Account 模型、控制平面与数据平面分离。</li></ul><h4 id="squid-版本迁移与-iam-集成" tabindex="-1"><strong>Squid 版本迁移与 IAM 集成</strong> <a class="header-anchor" href="#squid-版本迁移与-iam-集成" aria-label="Permalink to &quot;**Squid 版本迁移与 IAM 集成**&quot;">​</a></h4><ul><li><strong>迁移目标</strong>：临时凭证、身份联邦。</li><li><strong>迁移挑战</strong>：兼容性问题、无缝迁移。</li><li><strong>IAM 功能落地</strong>：临时凭证优势、控制限制。</li></ul><h4 id="性能与安全优化" tabindex="-1"><strong>性能与安全优化</strong> <a class="header-anchor" href="#性能与安全优化" aria-label="Permalink to &quot;**性能与安全优化**&quot;">​</a></h4><ul><li><strong>QoS 层</strong>：自研全局流量控制。</li><li><strong>监控</strong>：租户级实时指标、自动化测试集群。</li><li><strong>安全</strong>：全链路 HTTPS、静态加密、跨数据中心容灾。</li></ul><h4 id="问答环节重点" tabindex="-1"><strong>问答环节重点</strong> <a class="header-anchor" href="#问答环节重点" aria-label="Permalink to &quot;**问答环节重点**&quot;">​</a></h4><ul><li><strong>容器化部署</strong>：当前为裸金属集群，但控制平面与 Ceph 解耦。</li><li><strong>延迟影响</strong>：STS 凭证性能与长期凭证相当，部分场景更优。</li><li><strong>元数据库</strong>：使用 PostgreSQL + Airflow 自动化，未出现瓶颈。</li><li><strong>权限检查</strong>：IAM 策略通过标准 S3 协议处理，无额外延迟层。</li></ul><h4 id="后续行动计划" tabindex="-1"><strong>后续行动计划</strong> <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;**后续行动计划**&quot;">​</a></h4><ul><li><strong>IAM 完善</strong>：逐步开放 <code>Condition</code> 和 <code>Deny</code> 策略支持。</li><li><strong>身份联邦</strong>：集成 Bloomberg SSO（OIDC）。</li><li><strong>工具链</strong>：发布内部认证的 S3 客户端库。</li><li><strong>问题修复</strong>：跟踪 Squid 社区 PR。</li></ul><h4 id="总结" tabindex="-1"><strong>总结</strong> <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;**总结**&quot;">​</a></h4><p>Bloomberg 通过 Ceph RGW 构建了金融级对象存储服务，实现了多租户隔离、IAM 精细化管控和自动化运维，满足了海量高安全性需求。</p>',17)])])}const c=o(n,[["render",l]]);export{u as __pageData,c as default};
